sys_script_include.script:
var CheckUniquenessUtils = Class.create();
CheckUniquenessUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isAbhaNumberUnique: function() {
        var numVal = this.getParameter('sysparm_number_val');
        var currentSysId = this.getParameter('sysparm_current_id');

        var gr = new GlideRecord('x_2223823_apollo_0_patient');
        gr.addQuery('abha_number', numVal);
        // Exclude the current record if it's an existing record being updated
        if (currentSysId) {
            gr.addQuery('sys_id', '!=', currentSysId);
        }
        gr.query();

        return !gr.hasNext();
    },

    type: 'CheckUniquenessUtils'
});
